-- OFFLINE fixture only: no production migration. Original Stage27/28 definitions unchanged.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_managed_derived') IS NULL OR to_regnamespace('design_managed_normalized') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_normalized_storage_issuer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_normalized_verifier_authorizer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_normalized_verifier LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_normalized_storage_issuer,design_normalized_verifier_authorizer,design_normalized_verifier;
CREATE SCHEMA design_managed_normalized AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_managed_normalized FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_managed_normalized TO design_identity_runtime,design_normalized_storage_issuer,design_normalized_verifier_authorizer,design_normalized_verifier,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_managed_normalized TO design_managed_image_capability;
CREATE TABLE design_managed_normalized.permissions(id text PRIMARY KEY,authority jsonb NOT NULL,intent jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE UNIQUE INDEX normalized_permission_artifact ON design_managed_normalized.permissions ((intent->'artifact'->>'id'));
CREATE UNIQUE INDEX normalized_permission_request ON design_managed_normalized.permissions ((authority->>'subjectId'),(authority->>'employmentId'),(authority->>'membershipId'),(authority->>'storeId'),(intent->'artifact'->>'requestId'));
CREATE TABLE design_managed_normalized.put_claims(artifact_digest text PRIMARY KEY,permission_id text NOT NULL REFERENCES design_managed_normalized.permissions,intent jsonb NOT NULL);
CREATE UNIQUE INDEX normalized_claim_request ON design_managed_normalized.put_claims ((intent->'artifact'->'authority'->>'subjectId'),(intent->'artifact'->'authority'->>'employmentId'),(intent->'artifact'->'authority'->>'membershipId'),(intent->'artifact'->'authority'->>'storeId'),(intent->'artifact'->>'requestId'));
CREATE TABLE design_managed_normalized.objects(artifact_digest text PRIMARY KEY REFERENCES design_managed_normalized.put_claims,receipt jsonb NOT NULL);
CREATE TABLE design_managed_normalized.tasks(id text PRIMARY KEY,authority jsonb NOT NULL,artifact_digest text NOT NULL REFERENCES design_managed_normalized.objects,object_digest text NOT NULL,verifier jsonb NOT NULL,policy_version text NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_managed_normalized.reports(task_id text PRIMARY KEY REFERENCES design_managed_normalized.tasks,report jsonb NOT NULL,active boolean NOT NULL DEFAULT true);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['permissions','put_claims','objects','tasks','reports'] LOOP EXECUTE format('ALTER TABLE design_managed_normalized.%I OWNER TO design_identity_owner',t);EXECUTE format('ALTER TABLE design_managed_normalized.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_managed_normalized.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY capability_only ON design_managed_normalized.%I TO design_managed_image_capability USING(true) WITH CHECK(true)',t);EXECUTE format('GRANT SELECT,INSERT ON design_managed_normalized.%I TO design_managed_image_capability',t);EXECUTE format('CREATE TRIGGER normalized_immutable BEFORE UPDATE OR DELETE ON design_managed_normalized.%I FOR EACH ROW EXECUTE FUNCTION design_managed_image.immutable_row()',t);END LOOP;END$$;
GRANT UPDATE(active) ON design_managed_normalized.permissions,design_managed_normalized.tasks,design_managed_normalized.reports TO design_managed_image_capability;
CREATE FUNCTION design_managed_normalized.issuer_auth(token text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN
 IF (session_user NOT IN ('design_normalized_storage_issuer','design_normalized_verifier_authorizer','design_normalized_verifier') OR token IS NULL OR length(token) NOT BETWEEN 32 AND 200 OR token~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(token,'UTF8')),'hex'),scope);
 IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;RETURN r->'authority';END$$;
-- Exact trusted parent rows, not latest-response lookup and not caller hashes.
-- Uses the existing capability owner's rights; no old function/ACL is changed.
CREATE FUNCTION design_managed_normalized.check_artifact(a jsonb,n jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE rd text;s jsonb;o jsonb;v jsonb;t jsonb;maxbytes bigint;BEGIN
 IF (NOT design_managed_image.exact(n,ARRAY['schemaVersion','id','requestId','authority','sourceRecord','parentResponse','parentObjectReceipt','normalizationPolicy','output','state','validation','submissionAuthorized','adoptionAuthorized','publicEligible']) OR n->>'schemaVersion' IS DISTINCT FROM 'design-managed-image-normalization-v1' OR n->'authority' IS DISTINCT FROM a OR jsonb_typeof(n->'requestId') IS DISTINCT FROM 'string' OR n->>'requestId'!~'^[A-Za-z0-9_-]{1,100}$' OR n->>'state' IS DISTINCT FROM 'pending_validation' OR n->'submissionAuthorized' IS DISTINCT FROM 'false'::jsonb OR n->'adoptionAuthorized' IS DISTINCT FROM 'false'::jsonb OR n->'publicEligible' IS DISTINCT FROM 'false'::jsonb OR n->'validation' IS DISTINCT FROM '{"sourceBinding":"not_verified","parentBinding":"not_verified","fullDecode":"not_verified","metadataRemoval":"not_verified","orientation":"not_verified","color":"not_verified","geometry":"not_verified"}'::jsonb) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_ARTIFACT_INVALID' USING ERRCODE='42501';END IF;
 rd:=design_managed_derived.check_response(a,n->'parentResponse');
 SELECT record INTO STRICT s FROM design_managed_image.sources WHERE digest=n->'parentResponse'->>'sourceRecordDigest' AND active;
 SELECT receipt INTO STRICT o FROM design_managed_derived.objects WHERE response_digest=rd;
 PERFORM design_managed_derived.check_object(a,rd,o);
 IF (n->'sourceRecord' IS DISTINCT FROM s OR n->'parentObjectReceipt' IS DISTINCT FROM o OR o->'derivative'->>'mime' NOT IN ('image/jpeg','image/webp')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_PARENT_INVALID' USING ERRCODE='42501';END IF;
 IF (n->'normalizationPolicy' IS DISTINCT FROM '{"id":"managed-imgproxy-png-normalization","version":"1","runtime":{"id":"supabase-imgproxy","version":"3.8.0","imageDigest":"sha256:0facd355d50f3be665ebe674486f2b2e9cdaebd3f74404acd9b7fece2f661435"},"inputMimeTypes":["image/jpeg","image/webp"],"outputMime":"image/png","resize":"none","parentOrientation":"absent_or_identity","color":"srgb","pixelEquality":"exact_srgb","metadata":"strip_all","maximumFrames":1,"containerNormalization":"remove_pHYs_only","outputPixelFormat":"rgb8_noninterlaced"}'::jsonb) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_POLICY_INVALID' USING ERRCODE='42501';END IF;
 v:=n->'output';t:=n->'parentResponse'->'descriptor'->'requestedTransform';maxbytes:=CASE t->>'maxEdge' WHEN '1024' THEN 262144 WHEN '1536' THEN 524288 ELSE 0 END;
 IF (NOT design_managed_image.exact(v,ARRAY['sha256','byteLength','mime','width','height']) OR NOT design_managed_image.strings(v,ARRAY['sha256','mime']) OR v->>'sha256'!~'^[a-f0-9]{64}$' OR v->>'mime' IS DISTINCT FROM 'image/png' OR jsonb_typeof(v->'byteLength') IS DISTINCT FROM 'number' OR v->>'byteLength'!~'^[1-9][0-9]*$' OR (v->>'byteLength')::bigint NOT BETWEEN 1 AND maxbytes OR v->'width' IS DISTINCT FROM t->'width' OR v->'height' IS DISTINCT FROM t->'height' OR n->>'id' IS DISTINCT FROM 'normalization-'||design_dependency_authority.digest(n-'id')) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_OUTPUT_INVALID' USING ERRCODE='42501';END IF;
 RETURN design_dependency_authority.digest(n);END$$;
CREATE FUNCTION design_managed_normalized.check_put(a jsonb,i jsonb) RETURNS text LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE ad text;t jsonb;s jsonb;b jsonb;BEGIN
 IF (NOT design_managed_image.exact(i,ARRAY['schemaVersion','artifact','target','cost']) OR i->>'schemaVersion' IS DISTINCT FROM 'design-managed-normalized-put-intent-v1') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 ad:=design_managed_normalized.check_artifact(a,i->'artifact');s:=i->'artifact'->'sourceRecord';t:=i->'target';b:=i->'cost';
 IF (t IS DISTINCT FROM jsonb_build_object('projectOrigin',s->'object'->'projectOrigin','bucket',s->'object'->'bucket','key','managed-normalized/'||ad||'/object') OR NOT design_managed_image.exact(b,ARRAY['currency','maximumMinorUnits','maximumDispatches','commitment']) OR NOT design_managed_image.strings(b,ARRAY['currency','commitment']) OR b->>'currency'!~'^[A-Z]{3}$' OR jsonb_typeof(b->'maximumMinorUnits') IS DISTINCT FROM 'number' OR b->>'maximumMinorUnits'!~'^[1-9][0-9]*$' OR (b->>'maximumMinorUnits')::bigint NOT BETWEEN 1 AND 100000000 OR b->'maximumDispatches' IS DISTINCT FROM '1'::jsonb OR b->>'commitment' IS DISTINCT FROM 'one_time') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;RETURN ad;END$$;
CREATE FUNCTION design_managed_normalized.permission(a jsonb,i jsonb) RETURNS design_managed_normalized.permissions LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE p design_managed_normalized.permissions;BEGIN PERFORM design_managed_normalized.check_put(a,i);SELECT * INTO STRICT p FROM design_managed_normalized.permissions WHERE intent=i FOR SHARE;IF (NOT p.active OR p.authority IS DISTINCT FROM a OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;RETURN p;END$$;
CREATE FUNCTION design_managed_normalized.issue_put(token text,scope jsonb,id text,i jsonb,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;ad text;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalized_storage_issuer' OR id IS NULL OR id!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 a:=design_managed_normalized.issuer_auth(token,scope);ad:=design_managed_normalized.check_put(a,i);IF EXISTS(SELECT 1 FROM design_managed_normalized.put_claims WHERE artifact_digest=ad) THEN RAISE EXCEPTION 'NORMALIZED_ALREADY_CLAIMED';END IF;
 INSERT INTO design_managed_normalized.permissions VALUES(id,a,i,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_managed_normalized.permission(design_managed_normalized.issuer_auth(token,scope),i);RETURN true;END$$;
CREATE FUNCTION design_managed_normalized.guard_put(i jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_normalized.permissions;c design_managed_normalized.put_claims;BEGIN a:=design_managed_image.auth();p:=design_managed_normalized.permission(a,i);SELECT * INTO STRICT c FROM design_managed_normalized.put_claims WHERE artifact_digest=design_dependency_authority.digest(i->'artifact');IF (c.intent IS DISTINCT FROM i OR c.permission_id IS DISTINCT FROM p.id OR design_managed_image.auth() IS DISTINCT FROM a OR p.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_managed_normalized.claim_put(i jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;p design_managed_normalized.permissions;ad text;c design_managed_normalized.put_claims;BEGIN a:=design_managed_image.auth();p:=design_managed_normalized.permission(a,i);ad:=design_dependency_authority.digest(i->'artifact');SELECT * INTO c FROM design_managed_normalized.put_claims WHERE artifact_digest=ad;IF FOUND THEN IF (c.intent IS DISTINCT FROM i OR c.permission_id IS DISTINCT FROM p.id) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED';END IF;RETURN 'already_claimed';END IF;INSERT INTO design_managed_normalized.put_claims VALUES(ad,p.id,i);PERFORM design_managed_normalized.guard_put(i);RETURN 'created';END$$;
CREATE FUNCTION design_managed_normalized.check_object(a jsonb,ad text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c design_managed_normalized.put_claims;p design_managed_normalized.permissions;BEGIN
 SELECT * INTO STRICT c FROM design_managed_normalized.put_claims WHERE artifact_digest=ad;p:=design_managed_normalized.permission(a,c.intent);
 IF (c.permission_id IS DISTINCT FROM p.id OR NOT design_managed_image.exact(r,ARRAY['schemaVersion','artifactDigest','object','output','private','readbackVerified']) OR r->>'schemaVersion' IS DISTINCT FROM 'design-managed-normalized-object-v1' OR r->>'artifactDigest' IS DISTINCT FROM ad OR r->'private' IS DISTINCT FROM 'true'::jsonb OR r->'readbackVerified' IS DISTINCT FROM 'true'::jsonb OR r->'output' IS DISTINCT FROM c.intent->'artifact'->'output' OR NOT design_managed_image.exact(r->'object',ARRAY['projectOrigin','bucket','key','version']) OR ((r->'object')-'version') IS DISTINCT FROM c.intent->'target' OR jsonb_typeof(r->'object'->'version') IS DISTINCT FROM 'string' OR r->'object'->>'version'!~'^[A-Za-z0-9._-]{1,160}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('artifact',c.intent->'artifact','objectReceipt',r);END$$;
CREATE FUNCTION design_managed_normalized.publish_object(ad text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;old jsonb;BEGIN a:=design_managed_image.auth();PERFORM design_managed_normalized.check_object(a,ad,r);SELECT receipt INTO old FROM design_managed_normalized.objects WHERE artifact_digest=ad;IF FOUND THEN IF (old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_CONFLICT';END IF;ELSE INSERT INTO design_managed_normalized.objects VALUES(ad,r);END IF;RETURN design_managed_normalized.check_object(design_managed_image.auth(),ad,r);END$$;
CREATE FUNCTION design_managed_normalized.read_object(ad text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT receipt INTO STRICT r FROM design_managed_normalized.objects WHERE artifact_digest=ad;RETURN design_managed_normalized.check_object(a,ad,r);END$$;
CREATE FUNCTION design_managed_normalized.issue_task(token text,scope jsonb,id text,ad text,v jsonb,pv text,ttl bigint) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_normalized_verifier_authorizer' OR id IS NULL OR id!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000 OR NOT design_managed_image.exact(v,ARRAY['id','version']) OR NOT design_managed_image.strings(v,ARRAY['id','version']) OR v->>'id'!~'^[A-Za-z0-9_-]{1,100}$' OR v->>'version'!~'^[A-Za-z0-9._-]{1,160}$' OR pv IS NULL OR pv!~'^[A-Za-z0-9._-]{1,160}$') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 a:=design_managed_normalized.issuer_auth(token,scope);SELECT receipt INTO STRICT r FROM design_managed_normalized.objects WHERE artifact_digest=ad;PERFORM design_managed_normalized.check_object(a,ad,r);
 INSERT INTO design_managed_normalized.tasks VALUES(id,a,ad,design_dependency_authority.digest(r),v,pv,clock_timestamp()+ttl*interval '1 millisecond',true);PERFORM design_managed_normalized.task_context(design_managed_normalized.issuer_auth(token,scope),id);RETURN true;END$$;
CREATE FUNCTION design_managed_normalized.task_context(a jsonb,id text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE t design_managed_normalized.tasks;r jsonb;c jsonb;BEGIN
 SELECT * INTO STRICT t FROM design_managed_normalized.tasks WHERE tasks.id=task_context.id FOR SHARE;
 IF (NOT t.active OR t.authority IS DISTINCT FROM a OR t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 SELECT receipt INTO STRICT r FROM design_managed_normalized.objects WHERE artifact_digest=t.artifact_digest;c:=design_managed_normalized.check_object(a,t.artifact_digest,r);
 IF (design_dependency_authority.digest(r) IS DISTINCT FROM t.object_digest OR t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;
 RETURN c||jsonb_build_object('taskId',id,'verifier',t.verifier,'policyVersion',t.policy_version);END$$;
CREATE FUNCTION design_managed_normalized.binding(c jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE n jsonb;s jsonb;p jsonb;o jsonb;r jsonb;BEGIN
 n:=c->'artifact';s:=n->'sourceRecord';p:=n->'parentResponse';o:=n->'parentObjectReceipt';r:=c->'objectReceipt';
 RETURN jsonb_build_object('schemaVersion','design-managed-normalized-verification-binding-v1','artifactDigest',design_dependency_authority.digest(n),'requestId',n->'requestId','authority',n->'authority','scope',n->'authority'->'scope',
 'sourceRecordDigest',design_dependency_authority.digest(s),'sourceObject',s->'object','sourceSha256',s->'source'->'sha256','parentResponseDigest',design_dependency_authority.digest(p),'parentObjectReceiptDigest',design_dependency_authority.digest(o),'parentObject',o->'object','parentSha256',o->'derivative'->'sha256',
 'transformDigest',design_dependency_authority.digest(p->'descriptor'->'requestedTransform'),'normalizationPolicyDigest',design_dependency_authority.digest(n->'normalizationPolicy'),'output',n->'output','taskId',c->'taskId','normalizedObjectReceiptDigest',design_dependency_authority.digest(r),'normalizedObject',r->'object','normalizedSha256',r->'output'->'sha256','verifier',c->'verifier','policyVersion',c->'policyVersion');END$$;
CREATE FUNCTION design_managed_normalized.read_task(token text,scope jsonb,id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c jsonb;BEGIN IF (session_user IS DISTINCT FROM 'design_normalized_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_normalized.issuer_auth(token,scope);c:=design_managed_normalized.task_context(a,id);IF (c IS DISTINCT FROM design_managed_normalized.task_context(design_managed_normalized.issuer_auth(token,scope),id)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED';END IF;RETURN c;END$$;
CREATE FUNCTION design_managed_normalized.guard_task(token text,scope jsonb,id text,b jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;c jsonb;BEGIN IF (session_user IS DISTINCT FROM 'design_normalized_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_normalized.issuer_auth(token,scope);c:=design_managed_normalized.task_context(a,id);IF (b IS DISTINCT FROM design_managed_normalized.binding(c) OR design_managed_normalized.issuer_auth(token,scope) IS DISTINCT FROM a) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;PERFORM design_managed_normalized.task_context(a,id);RETURN true;END$$;
CREATE FUNCTION design_managed_normalized.check_report(a jsonb,id text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE c jsonb;b jsonb;checks jsonb;allgood boolean;anybad boolean;e jsonb;BEGIN
 c:=design_managed_normalized.task_context(a,id);b:=design_managed_normalized.binding(c);checks:=r->'checks';
 IF (NOT design_managed_image.exact(r,ARRAY['schemaVersion','state','verificationBinding','checks','evidence','submissionAuthorized','adoptionAuthorized','publicEligible']) OR r->>'schemaVersion' IS DISTINCT FROM 'design-managed-normalized-verification-report-v1' OR r->'verificationBinding' IS DISTINCT FROM b OR r->'submissionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'adoptionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'publicEligible' IS DISTINCT FROM 'false'::jsonb OR NOT design_managed_image.exact(checks,ARRAY['sourceBinding','parentBinding','fullDecode','metadataRemoval','orientation','color','geometry']) OR NOT design_managed_image.strings(checks,ARRAY['sourceBinding','parentBinding','fullDecode','metadataRemoval','orientation','color','geometry']) OR EXISTS(SELECT 1 FROM jsonb_each_text(checks) WHERE value NOT IN ('unknown','failed','verified'))) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_REPORT_INVALID' USING ERRCODE='42501';END IF;
 SELECT bool_and(value='verified'),bool_or(value='failed') INTO allgood,anybad FROM jsonb_each_text(checks);
 IF (r->>'state' IS DISTINCT FROM CASE WHEN anybad THEN 'validation_failed' WHEN allgood THEN 'evidence_complete' ELSE 'pending_validation' END) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_REPORT_INVALID' USING ERRCODE='42501';END IF;
 IF allgood THEN e:=jsonb_build_object('schemaVersion','design-managed-normalized-evidence-v1','id','normalized-verification-'||design_dependency_authority.digest(jsonb_build_object('binding',b,'checks',checks)),'verificationBindingDigest',design_dependency_authority.digest(b),'verifier',c->'verifier','policyVersion',c->'policyVersion','checks',checks);ELSE e:='null'::jsonb;END IF;
 IF (r->'evidence' IS DISTINCT FROM e) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_EVIDENCE_INVALID' USING ERRCODE='42501';END IF;
 PERFORM design_managed_normalized.task_context(a,id);RETURN c||jsonb_build_object('verificationReport',r);END$$;
CREATE FUNCTION design_managed_normalized.publish_report(token text,scope jsonb,id text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;old jsonb;BEGIN IF (session_user IS DISTINCT FROM 'design_normalized_verifier') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;a:=design_managed_normalized.issuer_auth(token,scope);PERFORM design_managed_normalized.check_report(a,id,r);SELECT report INTO old FROM design_managed_normalized.reports WHERE task_id=id;IF FOUND THEN IF (NOT EXISTS(SELECT 1 FROM design_managed_normalized.reports WHERE task_id=id AND active) OR old IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_CONFLICT';END IF;ELSE INSERT INTO design_managed_normalized.reports VALUES(id,r,true);END IF;RETURN design_managed_normalized.check_report(design_managed_normalized.issuer_auth(token,scope),id,r);END$$;
CREATE FUNCTION design_managed_normalized.read_verification_status(id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT report INTO STRICT r FROM design_managed_normalized.reports WHERE task_id=id AND active;RETURN design_managed_normalized.check_report(a,id,r);END$$;
CREATE FUNCTION design_managed_normalized.read_verified(id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;r jsonb;BEGIN a:=design_managed_image.auth();SELECT report INTO STRICT r FROM design_managed_normalized.reports WHERE task_id=id AND active;IF (r->>'state' IS DISTINCT FROM 'evidence_complete') IS DISTINCT FROM false THEN RAISE EXCEPTION 'NORMALIZED_NOT_VERIFIED' USING ERRCODE='42501';END IF;RETURN design_managed_normalized.check_report(a,id,r);END$$;
CREATE FUNCTION design_managed_normalized.revoke(kind text,id text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n int;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));
 IF kind='permission' AND session_user='design_normalized_storage_issuer' THEN UPDATE design_managed_normalized.permissions SET active=false WHERE permissions.id=revoke.id AND active;
 ELSIF kind='task' AND session_user='design_normalized_verifier_authorizer' THEN UPDATE design_managed_normalized.tasks SET active=false WHERE tasks.id=revoke.id AND active;
 ELSIF kind='report' AND session_user='design_normalized_verifier' THEN UPDATE design_managed_normalized.reports SET active=false WHERE task_id=revoke.id AND active;
 ELSE RAISE EXCEPTION 'NORMALIZED_DENIED' USING ERRCODE='42501';END IF;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='design_managed_normalized' LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_managed_image_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_identity_runtime,design_normalized_storage_issuer,design_normalized_verifier_authorizer,design_normalized_verifier',f.sig);END LOOP;END$$;
